package io.github.ningpp.compat;

/** Replacement for System.Management.Automation.ProviderNotFoundException (generated by CSharpToJava converter). */
public class ProviderNotFoundException extends SessionStateException {
    public ProviderNotFoundException() { super(); }
    public ProviderNotFoundException(String message) { super(message); }
    public ProviderNotFoundException(String message, Throwable cause) { super(message, cause); }
}
